import{_ as o,a0 as i,w as p,s as f,I as s,x as t,a1 as r,A as a,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux系統上用encfs創建和管理加密文件夾 | LCTT x X-CMD","titleTemplate":false,"description":"Linux系統上用encfs創建和管理加密文件夾 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux系統上用encfs創建和管理加密文件夾 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux系統上用encfs創建和管理加密文件夾 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Create And Manage Encrypted Folders in Linux With encfs","title":"Linux系統上用encfs創建和管理加密文件夾","tag":"201311","desc":""},"relativePath":"201311/Create And Manage Encrypted Folders in Linux With encfs.md","filePath":"[post].md"}'),u={name:"201311/Create And Manage Encrypted Folders in Linux With encfs.md"};function d(x,e,m,c,g,h){const n=i("Link");return p(),f("div",null,[e[18]||(e[18]=s("h1",{id:"linux系統上用encfs創建和管理加密文件夾",tabindex:"-1"},[t("Linux系統上用encfs創建和管理加密文件夾 "),s("a",{class:"header-anchor",href:"#linux系統上用encfs創建和管理加密文件夾","aria-label":"Permalink to “Linux系統上用encfs創建和管理加密文件夾”"},"​")],-1)),s("p",null,[e[2]||(e[2]=t("如果你想使你計算機上的某些信息免於被窺視的話，可以看看這篇文字。保護信息的一種方法就是加密你的home目錄，但是一旦你登錄系統後，你的home目錄下的信息將暴露於外。過去，我已經寫過關於怎樣",-1)),r(n,{href:"http://tuxtweaks.com/2009/03/create-an-encrypted-folder-in-ubuntu-with-cryptkeeper/"},{default:a(()=>[...e[0]||(e[0]=[t("在你的系統上使用Cryptkeeper來創建加密的文件夾",-1)])]),_:1}),e[3]||(e[3]=t("。Cryptkeeper是一個圖形前端，後端是 ",-1)),e[4]||(e[4]=s("strong",null,"encfs",-1)),e[5]||(e[5]=t("。encfs允許你創建一個加密的文件夾，然後通過",-1)),r(n,{href:"http://fuse.sourceforge.net/"},{default:a(()=>[...e[1]||(e[1]=[t("FUSE",-1)])]),_:1}),e[6]||(e[6]=t("來掛載作為用户文件系統。在這篇教程裏，我會教你怎麼在Linux系統上的命令列下面使用encfs工具來創建和管理一個加密的文件夾。",-1))]),e[19]||(e[19]=l(`<p><img src="http://tuxtweaks.com/wp-content/uploads/2013/10/encfs.png" alt=""></p><h3 id="安裝encfs" tabindex="-1">安裝encfs <a class="header-anchor" href="#安裝encfs" aria-label="Permalink to “安裝encfs”">​</a></h3><p>如果你使用的是Ubuntu或者它的衍生版本中的一種如Linux Mint的話，在軟件源庫當中應該能找到encfs。這種情況，可以用下面的命令來安裝</p><pre><code>sudo apt-get install encfs
</code></pre><h3 id="用encfs創建加密文件夾" tabindex="-1">用encfs創建加密文件夾 <a class="header-anchor" href="#用encfs創建加密文件夾" aria-label="Permalink to “用encfs創建加密文件夾”">​</a></h3><p>一旦在系統中安裝好了encfs後，你就能在你的home目錄下創建一個加密的文件夾。在這個示例當中，我將會創建一個叫做tuxtweaks的加密文件夾，這通過終端窗口就可以完成。當創建一個新的文件夾的時候，你需要指定全路徑名，當然也可以使用如下所示的標準快捷方式。</p><pre><code>encfs ~/.tuxtweaks ~/tuxtweaks
</code></pre><p>這會創建兩個文件夾。第一個.<strong>tuxtweaks</strong>,它包含被加密的信息；第二個tuxtweaks，當你想要訪問信息的時候，解密的版本信息將會掛載到下面。如果這些文件夾都不存在，系統將會提示詢問是否創建它們。在提示下面鍵入‘<strong>y</strong>’以允許創建文件夾，然後你應該能看到如下所示的一些信息：</p><pre><code>Creating new encrypted volume.
Please choose from one of the following options:
 enter &quot;x&quot; for expert configuration mode,
 enter &quot;p&quot; for pre-configured paranoia mode,
 anything else, or an empty line will select standard mode.
</code></pre><p>如果你想要最高級別的加密文件夾的話，在提示符下輸入<strong>p</strong>選項。否則只需敲擊<strong>[Enter]鍵</strong>，就會以標準選項來創建新的加密文件夾。</p><p>之後，你將會看到新加密卷的參數列表及一些警告信息，隨之提示符會讓輸入一個密碼。確保不要忘記使用的密碼，因為沒有密碼找回機制。在輸入密碼並以第二次輸入校驗通過後，新的文件夾會被創建成功，並自動掛載進文件系統，可以開始使用了。</p><h3 id="使用加密文件夾" tabindex="-1">使用加密文件夾 <a class="header-anchor" href="#使用加密文件夾" aria-label="Permalink to “使用加密文件夾”">​</a></h3><p>一旦新加密文件夾被掛載上，它就跟你係統上的其它文件夾一樣的使用，但如果你把它設置為paranoia模式的話，使用它的硬鏈接會出現不可用的異常。我想，這對大多數用户來説並不是問題。讓我們繼續吧，在新文件夾裏創建一個簡單的文本文件，然後用它來做測試。</p><pre><code>echo &quot;GNU/Linux is my favorite computer operating system.&quot; &gt;~/tuxtweaks/test.txt
</code></pre><p>在終端下或在文件系統管理器下，你都能看到在<strong>tuxtweaks</strong>目錄裏已經有一個叫做<strong>test.txt</strong>的新文件。打開此文件可看到這裏一個完全可讀的文本文件。現在切換到<strong>~/.tuxtweaks</strong>目錄下，這是你文件夾的加密版本，可以看到這裏的文件名不一樣了，如裏你查看此文件的內容話，會發現是亂糟糟的。</p><h3 id="卸載encfs創建的加密文件夾" tabindex="-1">卸載encfs創建的加密文件夾 <a class="header-anchor" href="#卸載encfs創建的加密文件夾" aria-label="Permalink to “卸載encfs創建的加密文件夾”">​</a></h3><p>一旦你完成文件訪問或者數據創建等操作，最好把加密文件夾卸載，以便裏面的信息安全的隱藏掉。encfs自身不帶有卸載的命令，一旦用它創建了用户文件系統，就可以利用FUSE來處理卸載任務。下面我們會使用fusermount命令來卸載我們的加密文件夾。</p><pre><code>fusermount -u ~/tuxtweaks
</code></pre><p>切換到home目錄下，會看到tuxtweaks目錄仍然存在，但進入文件夾，你會發現裏面是空的。（譯註：因為tuxtweaks目錄只是一個掛載點，真實的數據是以加密的方式存儲在.tuxtweaks目錄下的，）</p><h3 id="掛載用encfs創建的加密文件夾" tabindex="-1">掛載用encfs創建的加密文件夾 <a class="header-anchor" href="#掛載用encfs創建的加密文件夾" aria-label="Permalink to “掛載用encfs創建的加密文件夾”">​</a></h3><p>下一次你想要訪問加密數據的話，你需要重新加載並解密它，僅僅只需要使用跟我們在第一步創建此文件夾相同的命令就可以。</p><pre><code>encfs ~/.tuxtweaks ~/tuxtweaks
</code></pre><h3 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to “用途”">​</a></h3><p>我發現使用<strong>encfs</strong>加密文件夾來安全地存儲財務信息非常便捷，比如納税申報表以及用於存儲日誌列表憑據。這樣我只需要記住我加密文件夾的密碼，然後就可以進入訪問記錄有其他登錄ID和密碼的名單文件。</p><p>你會使用encfs來做什麼呢？在評論中給我們分享吧。</p><hr>`,26)),s("p",null,[e[8]||(e[8]=t("via: ",-1)),r(n,{href:"http://tuxtweaks.com/2013/10/encrypted-folders-linux-encfs/"},{default:a(()=>[...e[7]||(e[7]=[t("http://tuxtweaks.com/2013/10/encrypted-folders-linux-encfs/",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=t("譯者：",-1)),r(n,{href:"https://github.com/runningwater"},{default:a(()=>[...e[9]||(e[9]=[t("runningwater",-1)])]),_:1}),e[12]||(e[12]=t(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[15]||(e[15]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原創翻譯，",-1)),r(n,{href:"http://linux.cn/"},{default:a(()=>[...e[14]||(e[14]=[t("Linux中國",-1)])]),_:1}),e[17]||(e[17]=t(" 榮譽推出",-1))])])}const C=o(u,[["render",d]]);export{L as __pageData,C as default};
